"use client";

import { Bebas_Neue, Space_Grotesk } from "next/font/google";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowLeft, Menu, X, ChevronRight, FileText } from "lucide-react";
import Link from "next/link";
import { useState, useEffect } from "react";

const bebasNeue = Bebas_Neue({
  weight: "400",
  subsets: ["latin"],
  display: "swap",
});

const spaceGrotesk = Space_Grotesk({
  subsets: ["latin"],
  display: "swap",
});

const QUESTIONS = [
  { id: "q1", label: "Hangi meslekler dönüşecek?", title: "Yapay Zeka ve Otomasyon Önümüzdeki 10-20 Yılda Hangi Meslekleri Dönüştürebilir?" },
  { id: "q2", label: "Eski çalışanlara ne olacak?", title: "Yeni meslekler ortaya çıksa bile, eski mesleklerin çalışanları ne olacak?" },
  { id: "q3", label: "İnsan emeğinin değeri", title: "İnsan emeğinin ekonomik değeri nasıl değişebilir?" },
  { id: "q4", label: "Üretim ve Zenginlik", title: "Üretim Artarken Neden Herkes Aynı Ölçüde Zenginleşmeyebilir?" },
  { id: "q5", label: "Çalışma Saatleri", title: "Çalışma Saatlerinin Azaltılması Ekonomik Olarak Mümkün Olabilir mi?" },
  { id: "q6", label: "Ekonomik Bağımsızlık", title: "Gelecekte bir insanın ekonomik bağımsızlığa sahip olması için neye ihtiyacı olacak?" }
];

export default function ArticlePage() {
  const [activeId, setActiveId] = useState("");
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);

  const handleScroll = () => {
    const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = (window.scrollY / totalHeight) * 100;
    setScrollProgress(progress);
  };

  useEffect(() => {
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const headerOffset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

      window.scrollTo({
        top: offsetPosition,
        behavior: "smooth"
      });
    }
    setIsMobileMenuOpen(false);
  };

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveId(entry.target.id);
          }
        });
      },
      { threshold: 0.5, rootMargin: "-80px 0px -50% 0px" }
    );

    QUESTIONS.forEach((q) => {
      const el = document.getElementById(q.id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <main className="min-h-screen bg-[#060608] text-white selection:bg-[#FF003C] selection:text-white font-sans relative overflow-x-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 bg-[linear-gradient(to_right,#0c0c0e_1px,transparent_1px),linear-gradient(to_bottom,#0c0c0e_1px,transparent_1px)] bg-[size:40px_40px] pointer-events-none opacity-10" />
      
      {/* Top Header */}
      <header className="w-full border-b border-zinc-900 bg-black/90 backdrop-blur-xl sticky top-0 z-50">
        {/* Progress Bar */}
        <div className="absolute bottom-0 left-0 h-[2px] bg-[#FF003C] transition-all duration-150 ease-out" style={{ width: `${scrollProgress}%` }} />
        
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <Link 
            href="/gelecek" 
            className="flex items-center gap-2 text-zinc-500 hover:text-white transition-colors font-mono text-[10px] md:text-xs font-bold"
          >
            <ArrowLeft className="w-3 h-3 md:w-4 h-4" /> GELECEK ANALİZLERİ
          </Link>
          
          <div className="flex items-center gap-4">
            <span className={`${bebasNeue.className} text-sm md:text-lg tracking-widest hidden sm:inline text-zinc-400`}>DOSYA #01: EKONOMİ</span>
            <button 
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden flex items-center gap-2 px-3 py-1.5 border border-zinc-800 bg-zinc-900/50 text-zinc-400 hover:text-white rounded-md transition-all"
            >
              <span className="font-mono text-[10px] font-bold uppercase tracking-widest">{isMobileMenuOpen ? "KAPAT" : "SORULAR"}</span>
              {isMobileMenuOpen ? <X size={16} /> : <Menu size={16} />}
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-6 flex flex-col lg:flex-row gap-12 py-12">
        {/* Left Sidebar Menu - Desktop */}
        <aside className="hidden lg:block w-72 shrink-0">
          <div className="sticky top-28 space-y-8">
            <div className="space-y-2">
              <span className="font-mono text-[10px] text-zinc-600 font-bold uppercase tracking-[0.2em]">İçindekiler</span>
              <div className="h-px w-full bg-zinc-900" />
            </div>
            <nav className="flex flex-col gap-1">
              {QUESTIONS.map((q) => (
                <button
                  key={q.id}
                  onClick={() => scrollToSection(q.id)}
                  className={`text-left py-3 px-4 text-sm font-medium transition-all border-l-2 ${
                    activeId === q.id 
                      ? "border-[#FF003C] text-white bg-zinc-900/50" 
                      : "border-transparent text-zinc-500 hover:text-zinc-300 hover:bg-zinc-900/30"
                  }`}
                >
                  {q.label}
                </button>
              ))}
            </nav>
          </div>
        </aside>

        {/* Mobile Menu Overlay */}
        <AnimatePresence>
          {isMobileMenuOpen && (
            <motion.div 
              initial={{ opacity: 0, x: -100 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -100 }}
              className="fixed inset-0 z-40 bg-black pt-24 px-6 lg:hidden"
            >
              <div className="space-y-6">
                <span className="font-mono text-xs text-zinc-600 font-bold uppercase tracking-widest block">SORULAR</span>
                <nav className="flex flex-col gap-4">
                  {QUESTIONS.map((q) => (
                    <button
                      key={q.id}
                      onClick={() => scrollToSection(q.id)}
                      className="text-left py-4 text-xl font-bold text-zinc-200 border-b border-zinc-900 flex items-center justify-between"
                    >
                      {q.label} <ChevronRight className="w-5 h-5 text-[#FF003C]" />
                    </button>
                  ))}
                </nav>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Article Content Area */}
        <article className="flex-1 max-w-3xl space-y-24 pb-32">
          {/* Main Title */}
          <header className="space-y-8">
            <motion.div 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="inline-flex items-center gap-2 px-3 py-1 bg-zinc-900 border border-zinc-800 text-zinc-400 rounded-full"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-[#FF003C]" />
              <span className="font-mono text-[10px] font-bold tracking-widest uppercase">STRATEJİK ANALİZ // 001</span>
            </motion.div>
            
            <motion.h1 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className={`${bebasNeue.className} text-5xl md:text-7xl lg:text-8xl font-black leading-tight tracking-tight uppercase text-zinc-100`}
            >
              YAPAY ZEKA VE <span className="text-[#FF003C]">İŞİN GELECEĞİ</span>
            </motion.h1>
            
            <div className="flex items-center gap-4 text-zinc-600 font-mono text-[10px] uppercase tracking-[0.2em]">
              <span>Okuma süresi: 8 dk</span>
              <span className="w-1 h-1 rounded-full bg-zinc-800" />
              <span>Kategori: Ekonomi</span>
            </div>
          </header>

          {/* Section 1 */}
          <section id="q1" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide leading-tight border-b border-zinc-900 pb-6`}>
              1. YAPAY ZEKA VE OTOMASYON ÖNÜMÜZDEKİ 10-20 YILDA HANGİ MESLEKLERİ DÖNÜŞTÜREBİLİR
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <p>
                Yapay zeka ve otomasyonun ilerleyişini düz bir çizgi olarak görmek hata olur. Yapay zeka ve otomasyonların ilerleyişi, bazen içine yeni bir kendisi büyüklüğünde kartopu giren kartopu gibidir.
              </p>
              <p>
                İlerledikçe hızlanır ama beklenmeyen bir anda çok hızlı büyüyebilir. İlk olarak bunu bilmek lazım ve buna göre çıkarım yapmak lazımdır.
              </p>
              <p>
                Aralık 2022'de ChatGPT tüm dünyada popüler oldu ve o zamandan bu zamana değişimi ve işimizi elimizden alma eğrisini (işsizliği sadece yapay zekaya bağlamak çok doğru olmasa da ekonomik krizle birleşince resmen kriz oldu) incelediğimizde, bu kartopu eğrisinin avuç kadar bir kütle iken nasıl bir bina büyüklüğüne geldiğini gördük.
              </p>
              <p>
                Biz önümüzdeki 5 yılı değil, 10-20 yılı düşünmek istiyoruz. O yüzden tarım ile uğraşmak gibi mantıklı görünen düşünceler bile yanlıştır; çünkü bir raddede, 10 yıl içinde yapay zeka tarafından ve hatta şimdi bile kolaylıkla yapılabilir.
              </p>
              
              <div className="bg-zinc-950 border-l-4 border-[#FF003C] p-6 space-y-4 my-8">
                <h4 className="text-white font-bold uppercase tracking-widest text-sm">Tahmin Edilen Meslek Kolları:</h4>
                <ul className="list-disc list-inside space-y-2 text-zinc-500">
                  <li>Ofis işlerini unutun artık, eskisi gibi özellikle virüs zamanındaki gibi o işler bize para kazandırmaz.</li>
                  <li>Yazılımın tamamen biteceği söylenebilir; sadece bu tür olayların mühendislik ve derin düşünme, ihtiyaca uygun ürün yaratma kolunda insanlar olacaktır.</li>
                  <li>Birçok mühendislik bitecektir; mühendislerin onda sekiz-dokuzunun işsiz kalacağını söylemek yanlış olmaz.</li>
                  <li>Doktorluk ve öğretmenlik gibi meslekler devam edecektir ama özel ders alma gibi olayların yarı yarıya düşeceğini söyleyebiliriz.</li>
                </ul>
              </div>

              <p className="font-bold text-white text-xl">Robotlar vs. İnsan</p>
              <p>
                Robot ve insan çalışan arasında belirgin bir fark olacak. Robot, büyük oranda işini profesyonel yapan, katı, başarı oranı yüksek, üretim hızı yüksek, maliyetinin belli bir ortalaması olan iken; insan, daha esnek ve ucuza kullanılabilecek bir işçiye dönüşebilir.
              </p>
              <p>
                Mesela arabanda ağır bir hasar olunca aracın fabrikanın robotlar tarafından işletilen yetkili servisine gidersen işin tam ve profesyonel şekilde hallolur ama maliyeti daha fazla olur. Bunun yanında, eğer mahalle aralarındaki küçük sanayiye gidersen işi daha ucuza ve daha kolay, pratik yollu tamirlerle halledebilirsin.
              </p>
              <p>
                Yani zanaat ve el işleri, ustalık işleri tamamen yok olmayıp bir tercih haline gelebilir. Kim bilir, belki insanlar gelecekte satın alacakları ürünlerde "İnsan Emeğidir / El Yapımı" ibaresi arayacak ve buna fazladan para ödeyecekler.
              </p>
            </div>
          </section>

          {/* Section 2 */}
          <section id="q2" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide border-b border-zinc-900 pb-6`}>
              2. Yeni meslekler ortaya çıksa bile, eski mesleklerin çalışanları ne olacak?
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <p>
                Basit iş gücü olarak sanayide, tarlada, fabrikada çalışabilirler. Zanaat yapıp belki bundan para kazanabilirler. Gelecekte zanaat ve sanat gibi konuların, eğlence kültürünün artmasını bekliyorum.
              </p>
              <p>
                Eğer eğlence kültürü haddinden fazla artarsa, sosyal medyadan kaynaklı zehirlenmiş, "hayatsız" diye tabir edilen depresif arkadaşlar çıkabilir. Bu evreyi tamamlayan ve "Yeter la!" diyen insanlar her şeyden uzaklaşıp kendi hayatını yaşamaya çalışabilir.
              </p>
              <p className="bg-white/5 p-6 border border-zinc-900 italic">
                "Her şeyi boşverip yapay zeka şirketlerinin diktatörlüğünü kırmak adına kitlesel örgütlenmelerle uğraşabilirler."
              </p>
              <p>
                Eğer evrensel temel gelir (maaş) verilmezse insanlara, olaylar çok daha kaotik bir duruma gelebilir. Devletler sırf işsiz insan olmasın diye herkesi bir işe bağlamaya çalışabilir. Askerlik oranları artabilir ve dünyadaki gerilimle savaşlar çıkabilir.
              </p>
            </div>
          </section>

          {/* Section 3 */}
          <section id="q3" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide border-b border-zinc-900 pb-6`}>
              3. İnsan emeğinin ekonomik değeri nasıl değişebilir?
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <p>
                İnsan emeğinin değeri, eğer nüfusta bir düşüş olmazsa kesin olarak düşecektir. Son zamanlarda insana değer sağlayan şey masa başı işlerdi ama bu işleri artık yapay zeka yapabilir hale geldi.
              </p>
              <p>
                İnsanlar diğer işlere yönelecekler ve herkes yöneldiği için o işlerin değeri düşecektir. Eğer uzay keşifleri ve kolonizasyonu başlarsa bunda şans var; insanlar belki bundan maaş alabilir ve birçok insan gitmesine rağmen değerli bir iş olarak görülebilir bu.
              </p>
              <p>
                Gelecekte sanatçılık ve zanaatkarlık önemli bir yere sahip olacak; bu işi yapan ve başarılı olan insanların değeri yüksek olacaktır. Ama genel olarak bu nüfusla seyredersek kesinlikle "ekonomik" değerimiz düşecektir.
              </p>
            </div>
          </section>

          {/* Section 4 */}
          <section id="q4" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide border-b border-zinc-900 pb-6`}>
              4. Üretim Artarken Neden Herkes Aynı Ölçüde Zenginleşmeyebilir?
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <p>
                Üretim artarken, üretimi sağlayan gücü kimlerin elinde tuttuğu çok önemlidir. Bu gücü elde tutanlar yapay zekanın halledebileceği her sektörde tekel haline gelebilir.
              </p>
              
              <div className="bg-zinc-900/50 p-8 border border-zinc-800 space-y-6">
                <h3 className={`${bebasNeue.className} text-2xl text-[#FF003C] tracking-widest`}>
                  YAPAY ZEKA VE KÜRESEL DENETİM ÇIKMAZI
                </h3>
                <p className="text-sm">
                  Yapay zekayı şirketlerden alıp insanlığa mal etmek mümkün mü? Teoride bu, tıpkı bilim gibi düşünülebilir; ancak pratikte gerçekleşmesinin önünde devasa engeller vardır:
                </p>
                <div className="space-y-4">
                  <div>
                    <span className="text-white font-bold block mb-1">1. Jeopolitik Rekabet:</span>
                    <p className="text-sm text-zinc-500">"Eğer ben durursam onlar beni geçer" korkusu, ulus-devletleri bu teknolojide fren yapmaktan alıkoyar.</p>
                  </div>
                  <div>
                    <span className="text-white font-bold block mb-1">2. Sermaye ve Mülkiyet:</span>
                    <p className="text-sm text-zinc-500">Büyük sermayenin "insanlık namına" değil, kâr etmek için yatırıldığı bir sistemde kamuya devir hayalcilik olur.</p>
                  </div>
                  <div>
                    <span className="text-white font-bold block mb-1">3. Hızın Fiyatı:</span>
                    <p className="text-sm text-zinc-500">Denetim mekanizmaları inovasyonu yavaşlatır. Şu anki ilerleme, kuralsızlığın bir ürünüdür.</p>
                  </div>
                </div>
              </div>
            </div>
          </section>

          {/* Section 5 */}
          <section id="q5" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide border-b border-zinc-900 pb-6`}>
              5. Çalışma Saatlerinin Azaltılması Ekonomik Olarak Mümkün Olabilir mi?
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <div className="grid md:grid-cols-2 gap-8">
                <div className="bg-zinc-950 p-6 border border-zinc-900">
                  <h4 className="text-emerald-500 font-bold mb-4 uppercase text-xs tracking-widest">Neden Mümkün?</h4>
                  <p className="text-sm">Yapay zeka verimliliği patlatırsa, bir kişinin 8 saatte ürettiği değeri 4 saatte üretebiliriz. Bu, kârlılıktan ödün vermeden çalışma süresini kısaltabilir.</p>
                </div>
                <div className="bg-zinc-950 p-6 border border-zinc-900">
                  <h4 className="text-[#FF003C] font-bold mb-4 uppercase text-xs tracking-widest">Neden Değil?</h4>
                  <p className="text-sm">İnsan emeği ucuzladıkça, hayatta kalabilmek için daha fazla çalışmak gerekebilir. Birim saat başına alım gücü azaldığı için kölelik benzeri bir zorunluluk doğabilir.</p>
                </div>
              </div>
            </div>
          </section>

          {/* Section 6 */}
          <section id="q6" className="scroll-mt-28 space-y-8">
            <h2 className={`${bebasNeue.className} text-3xl md:text-5xl text-white tracking-wide border-b border-zinc-900 pb-6`}>
              6. Gelecekte bir insanın ekonomik bağımsızlığa sahip olması için neye ihtiyacı olacak?
            </h2>
            <div className={`${spaceGrotesk.className} text-zinc-400 text-lg leading-relaxed space-y-6`}>
              <p>
                Eğer insanlar baskı yapıp yapay zeka şirketleri ve devletlerle kendi haklarını koruyacak mücadeleler verirse, gelecekte insan hala kendi ülkesinde egemen olabilir.
              </p>
              <p>
                Peki ya insanların yüzde 90'ından fazlasının vergi vermediği bir dünya düzenine geçersek, devletin bizi umursama sebebi ne olacak? Bunun tek kitlesel çözümü mücadele vermek ve gerekirse şirketleri regüle etmektir.
              </p>
              <div className="py-8 text-center border-y border-zinc-900 my-12">
                <p className={`${bebasNeue.className} text-4xl md:text-6xl text-white uppercase`}>
                  KİMSEYE GÜVENMEYİN VE <br />
                  <span className="text-[#FF003C]">SİZ DE BİZE KATILIN.</span>
                </p>
                <Link 
                  href="/#join" 
                  className="inline-block mt-8 bg-white text-black px-8 py-4 font-black tracking-widest hover:bg-[#FF003C] hover:text-white transition-all uppercase"
                >
                  HAREKETE GEÇ
                </Link>
              </div>
            </div>
          </section>
        </article>
      </div>

      {/* Footer */}
      <footer className="w-full py-12 px-6 border-t border-zinc-900 bg-black/50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-6">
          <span className={`${spaceGrotesk.className} text-xs font-mono text-zinc-600 uppercase tracking-widest`}>
            © 2026 YETER LA // DOSYA ANALİZ SİSTEMİ
          </span>
          <div className="flex gap-8">
            <Link href="/gelecek" className="text-zinc-500 hover:text-white transition-colors text-sm font-bold uppercase tracking-widest">
              DİĞER DOSYALAR
            </Link>
            <Link href="/" className="text-zinc-500 hover:text-white transition-colors text-sm font-bold uppercase tracking-widest">
              ANA SAYFA
            </Link>
          </div>
        </div>
      </footer>
    </main>
  );
}
